public class Solution {
    public int lengthOfLIS(int[] nums) {
        int[] tails = new int[nums.length];
        int sz = 0;
        for (int x : nums) {
            int l = 0, r = sz;
            while (l < r) {
                int m = l + (r - l) / 2;
                if (tails[m] < x) l = m + 1;
                else r = m;
            }
            tails[l] = x;
            if (l == sz) sz++;
        }
        return sz;
    }
}

